    public static final long PAGE_LOAD_TIMEOUT = Long.getLong("pageLoadTimeout", 30_000L);
    public static final long ELEMENT_TIMEOUT = Long.getLong("elementTimeout", 10_000L);
    private static final ThreadLocal<Long> SHORTER = new ThreadLocal<>();

    private WaitActions() {
    }

    /** A wait as a person reads it: "10" (seconds), or "0.5". */
    public static String seconds(long ms) {
        return ms % 1000 == 0 ? String.valueOf(ms / 1000) : String.valueOf(ms / 1000.0);
    }

